 void task(String name,long since,boolean success)throws Exception{waitFor("new task completes: "+name,()->{JSONArray a=((TaskJournal)field("journal")).snapshot();for(int i=0;i<a.length();i++){JSONObject t=a.getJSONObject(i);if(t.optString("name").equals(name)&&t.optLong("created")>=since&&!TaskJournal.active(t)){boolean good=t.optString("state").equals("success");if(good!=success)throw new AssertionError(t.toString());return true;}}return false;});}
