  set("installExpectedPackage","other.app");start=System.currentTimeMillis();inspect("upgrade-v2.apk");task("检查 APK 兼容性",start,false);waitFor("per-app update rejects another package",()->dialogHas("包名与要更新的电视应用不一致"));dialogTap("知道了");
  plan("upgrade-v2.apk");candidate=field("genericPlan");cached=((List<File>)files.get(candidate)).get(0);try(OutputStream out=new FileOutputStream(cached,true)){out.write(0);}start=System.currentTimeMillis();dialogTap("确认更新");task("安装或更新电视应用",start,false);waitFor("changed source APK stops before transfer",()->dialogHas("来源安装文件已变化"));dialogTap("知道了");check(version()==2,"changed source does not modify installed app");
